def compute_chunk_indices(total_length: int, chunk_size: int) -> list[tuple[int, int]]:
    if chunk_size <= 0 or total_length <= 0:
        return []
    chunks = []
    for start in range(0, total_length, chunk_size):
        end = start + chunk_size
        chunks.append((start, end))
    return chunks

