class Connection:
    def __init__(self) -> None:
        self.is_open: bool = False

    def open(self) -> None:
        self.is_open = True

    def close(self) -> None:
        self.is_open = False


def execute_transaction(conn: Connection, query: str) -> str:
    conn.open()
    if "FAIL" in query:
        raise RuntimeError("Query execution failed")
    result = f"RECORD:{query}"
    conn.close()
    return result

