def parse_query_param(query_string: str, param_name: str) -> str | None:
    if not query_string or "=" not in query_string:
        return None
    pairs = query_string.split("&")
    for pair in pairs:
        if "=" in pair:
            key, val = pair.split("=", 1)
            if key == param_name:
                return val
    return None

